    demand_variance = (float(mu) * float(cv)) * (float(mu) * float(cv))
    variances = [groups[0] * demand_variance, groups[1] * demand_variance]

    probabilities = [[1.0, 1.0], [1.0, 1.0]]
    weights = [[1.0, 0.0], [1.0, 0.0]]

