            shifted[i] = x[i + 1]

        if step < len(pipeline):
            arrival = float(pipeline[step])
            if arrival < 0.0:
                arrival = 0.0
            shifted[m - 1] = arrival
        else:
            shifted[m - 1] = 0.0

        x = shifted

    effective_inventory = 0.0
